#

sub new { TIEHASH(@_) }

sub Clear {
  my $s = shift;
  $s->[0] = {};   # hashkey index
  $s->[1] = [];   # array of keys
  $s->[2] = [];   # array of data
  $s->[3] = 0;    # iter count
